  wheel_=declare_parameter<std::string>("wheel_mode","rest"); const double oldwo=declare_parameter<double>("wheel_torque_extend_nm",0),oldwi=declare_parameter<double>("wheel_torque_contract_nm",0); wheel_out_=declare_parameter<double>("wheel_torque_outward_nm",oldwo);wheel_in_=declare_parameter<double>("wheel_torque_inward_nm",oldwi);L_=declare_parameter<double>("hip_to_wheel_m",.260);R_=declare_parameter<double>("wheel_radius_m",.051); valid(); wheel_code_=wheelCode(wheel_);
