 void openLog(){if(run_dir_.empty())return;fs::create_directories(run_dir_);trace_.open(fs::path(run_dir_)/"command_state_trace.csv");trace_<<"time_s,strategy_name,strategy_version,trial,phase,segment,module,hip_cmd_motor_rad,hip_cmd_actual_rad,hip_cmd_rate_rad_s,hip_ff_direct,hip_motor_rad,angle_diff_rad,hip_actual_rad,hip_vel_rad_s,hip_torque,hip_error_code,hub_mode,hub_cmd_value,hub_pos_rad,hub_vel_rad_s,hub_torque\n";std::ofstream o(fs::path(run_dir_)/"trial_manifest.yaml");o<<"strategy_name: "<<name_<<"\nstrategy_version: "<<version_<<"\nangle_convention: actual_hip_angle_rad = motor_position + position_diff\ncommand_topic: "<<topic_<<"\narmed: "<<(armed_?"true":"false")<<"\nmotion_mode: "<<mode_<<"\nsequence_outward_deg: [";for(size_t i=0;i<seq_.size();i++)o<<(i?", ":"")<<seq_[i];o<<"]\nrepetitions: "<<reps_<<"\nwheel_mode: "<<wheel_<<"\nkp: "<<kp_<<"\nki: "<<ki_<<"\nkd: "<<kd_<<"\nhip_ff_outward_direct: "<<ff_out_<<"\nhip_ff_inward_direct: "<<ff_in_<<"\nhip_ff_static_outward_direct: "<<ff_static_out_<<"\nhip_ff_static_inward_direct: "<<ff_static_in_<<"\n";}
 double a(size_t i,bool end)const{return active(i)?outsign(i)*seq_[seg_+(end?1:0)]*D2R:0;}double d(size_t i)const{return a(i,true)-a(i,false);}double recovery(size_t i)const{return active(i)?outsign(i)*recovery_deg_*D2R:0;}bool stat()const{return seg_==0&&seq_[0]==0&&seq_[1]>0;}double duration()const{double z=0;for(size_t i=0;i<4;i++)z=std::max(z,std::abs(d(i)));if(stat())z*=1-static_fraction_;return speed_>0?z/speed_:fallback_s_;}double moveDuration(bool recover)const{double z=0;for(size_t i=0;i<4;i++)z=std::max(z,std::abs((recover?recovery(i):a(i,false))-move_start_[i]));double v=recover?recovery_speed_:startup_speed_;return v>0?z/v:fallback_s_;}double elapsed()const{return(now()-t0_).seconds();}double frac()const{if(phase_==Phase::STARTUP_MOVE||phase_==Phase::RECOVERY_MOVE)return sm(elapsed()/moveDuration(phase_==Phase::RECOVERY_MOVE));if(phase_==Phase::STATIC_RELEASE)return static_fraction_*sm(elapsed()/static_s_);if(phase_==Phase::MOVE)return stat()?static_fraction_+(1-static_fraction_)*cl(elapsed()/duration()):cl(elapsed()/duration());if(phase_==Phase::HOLD)return 1;return 0;}double rate(size_t i)const{if(!active(i))return 0;if(phase_==Phase::STARTUP_MOVE||phase_==Phase::RECOVERY_MOVE){double u=cl(elapsed()/moveDuration(phase_==Phase::RECOVERY_MOVE));return ((phase_==Phase::RECOVERY_MOVE?recovery(i):a(i,false))-move_start_[i])*6*u*(1-u)/moveDuration(phase_==Phase::RECOVERY_MOVE);}if(phase_==Phase::MOVE)return d(i)*(stat()?1-static_fraction_:1)/duration();if(phase_==Phase::STATIC_RELEASE){double u=cl(elapsed()/static_s_);return d(i)*static_fraction_*6*u*(1-u)/static_s_;}return 0;}
