 double ff(size_t i,double r){if(!active(i)||(phase_!=Phase::STATIC_RELEASE&&(phase_!=Phase::MOVE||std::abs(r)<ff_rate_min_))){ff_on_[i]=false;return 0;}double e=cmd_[i]-actual(i);if(r*e<=0)ff_on_[i]=false;else if(!ff_on_[i]&&std::abs(e)>=ff_enable_)ff_on_[i]=true;else if(ff_on_[i]&&std::abs(e)<=ff_disable_)ff_on_[i]=false;if(!ff_on_[i])return 0;bool outward=r*outsign(i)>0;double mag=phase_==Phase::STATIC_RELEASE?(outward?ff_static_out_:ff_static_in_):(outward?ff_out_:ff_in_);return std::clamp(std::copysign(std::abs(mag),r),-ff_limit_,ff_limit_);}
 kilin_msgs::msg::MotorCmd hipCmd(size_t i){kilin_msgs::msg::MotorCmd c; if(phase_==Phase::STARTUP_MOVE)cmd_[i]=move_start_[i]+frac()*(a(i,false)-move_start_[i]);else if(phase_==Phase::RECOVERY_MOVE)cmd_[i]=move_start_[i]+frac()*(recovery(i)-move_start_[i]);else cmd_[i]=(phase_==Phase::STATIC_RELEASE||phase_==Phase::MOVE||phase_==Phase::HOLD)?a(i,false)+frac()*d(i):a(i,false);c.motor_mode=POS;c.position=cmd_[i]-hip_[i].d;c.kp=kp_;c.ki=ki_;c.kd=kd_;c.torque=ff(i,rate(i));return c;}kilin_msgs::msg::MotorCmd wheelCmd(size_t i,double r)const{kilin_msgs::msg::MotorCmd c;if(phase_==Phase::STARTUP_MOVE||phase_==Phase::RECOVERY_MOVE||phase_==Phase::RECOVERY_REST){c.motor_mode=REST;return c;}c.motor_mode=wheel_code_;double wr=-L_*std::cos(cmd_[i])*r/R_;if(wheel_code_==POS)c.position=hub0_[i];if(wheel_code_==SPEED)c.velocity=rpm10(wr);if(wheel_code_==TORQUE){bool outward=r*outsign(i)>0;double mag=(phase_==Phase::STATIC_RELEASE||phase_==Phase::MOVE)?(outward?wheel_out_:wheel_in_):0;c.torque=std::clamp(std::copysign(std::abs(mag),wr==0?1:wr),-hub_torque_limit_,hub_torque_limit_);}return c;}
 void hdr(kilin_msgs::msg::MotorCmdStamped&m){auto t=now();m.header.seq=serial_++;m.header.time.sec=(int)t.seconds();m.header.time.nanosec=t.nanoseconds()%1000000000LL;m.header.frame_id="kilin_hip_characterization";}void stop(){kilin_msgs::msg::MotorCmdStamped m;hdr(m);kilin_msgs::msg::LegCmd x;x.hip.motor_mode=REST;x.steering.motor_mode=REST;x.hub.motor_mode=BRAKE;m.module_a=x;m.module_b=x;m.module_c=x;m.module_d=x;pub_->publish(m);}
 void publish(){kilin_msgs::msg::MotorCmdStamped m;hdr(m);std::array<kilin_msgs::msg::LegCmd,4> x;for(size_t i=0;i<4;i++){x[i].hip=hipCmd(i);x[i].steering.motor_mode=POS;x[i].steering.position=0;x[i].hub=wheelCmd(i,rate(i));}m.module_a=x[0];m.module_b=x[1];m.module_c=x[2];m.module_d=x[3];pub_->publish(m);if(trace_)for(size_t i=0;i<4;i++){auto&h=x[i].hub;double hv=wheel_code_==POS?h.position:wheel_code_==SPEED?h.velocity:h.torque;trace_<<now().seconds()<<','<<name_<<','<<version_<<','<<trial_+1<<','<<(int)phase_<<','<<seg_<<','<<N[i]<<','<<x[i].hip.position<<','<<cmd_[i]<<','<<rate(i)<<','<<x[i].hip.torque<<','<<hip_[i].p<<','<<hip_[i].d<<','<<actual(i)<<','<<hip_[i].v<<','<<hip_[i].t<<','<<hip_[i].e<<','<<h.motor_mode<<','<<hv<<','<<hub_[i].p<<','<<hub_[i].v<<','<<hub_[i].t<<'\n';}}
 bool expired()const{return phase_==Phase::STARTUP_MOVE?elapsed()>=moveDuration(false):phase_==Phase::ZERO_HOLD?elapsed()>=zero_hold_:phase_==Phase::STATIC_RELEASE?elapsed()>=static_s_:phase_==Phase::MOVE?elapsed()>=duration():phase_==Phase::HOLD?elapsed()>=hold_s_:phase_==Phase::FINAL_HOLD?elapsed()>=final_hold_:phase_==Phase::RECOVERY_REST?elapsed()>=recovery_rest_s_:phase_==Phase::RECOVERY_MOVE?elapsed()>=moveDuration(true):false;}void advance(){t0_=now();if(phase_==Phase::STARTUP_MOVE)phase_=Phase::ZERO_HOLD;else if(phase_==Phase::ZERO_HOLD)phase_=stat()?Phase::STATIC_RELEASE:Phase::MOVE;else if(phase_==Phase::STATIC_RELEASE)phase_=Phase::MOVE;else if(phase_==Phase::MOVE)phase_=Phase::HOLD;else if(phase_==Phase::HOLD){if(++seg_+1<seq_.size())phase_=Phase::MOVE;else phase_=Phase::FINAL_HOLD;}else if(phase_==Phase::FINAL_HOLD){if(++trial_>=reps_)phase_=Phase::RECOVERY_REST;else{seg_=0;ff_on_.fill(false);phase_=Phase::ZERO_HOLD;}}else if(phase_==Phase::RECOVERY_REST){for(size_t i=0;i<4;i++)move_start_[i]=actual(i);phase_=Phase::RECOVERY_MOVE;}else if(phase_==Phase::RECOVERY_MOVE)phase_=Phase::DONE;}
